from __future__ import annotations

from typing import TYPE_CHECKING, Any

import numpy as np

from enn._rust import (
    arms_from_pareto_fronts as _rust_arms_from_pareto_fronts,
)
from enn._rust import (
    calculate_sobol_indices as _rust_calculate_sobol_indices,
)
from enn._rust import (
    pareto_front_2d_maximize as _rust_pareto_front_2d_maximize,
)
from enn._rust import (
    standardize_y as _rust_standardize_y,
)

if TYPE_CHECKING:
    from numpy.random import Generator


def standardize_y(y: np.ndarray | list[float] | Any) -> tuple[float, float]:
    y_array = np.asarray(y, dtype=float)
    center, scale = _rust_standardize_y(y_array)
    return float(center), float(scale)


def calculate_sobol_indices(x: np.ndarray, y: np.ndarray) -> np.ndarray:
    """Calculate Sobol indices using Rust backend."""
    if x.ndim != 2:
        raise ValueError(f"x must be 2D, got shape {x.shape}")
    n, d = x.shape
    if d <= 0:
        raise ValueError(f"x must have at least 1 dimension, got {d}")
    if y.ndim == 2 and y.shape[1] == 1:
        y = y.reshape(-1)
    if y.ndim != 1 or y.shape[0] != n:
        raise ValueError(f"y shape {y.shape} incompatible with x rows {n}")

    x_f64 = np.asarray(x, dtype=np.float64)
    y_f64 = np.asarray(y, dtype=np.float64)
    result = _rust_calculate_sobol_indices(x_f64, y_f64)
    return np.asarray(result, dtype=x.dtype)


def pareto_front_2d_maximize(
    a: np.ndarray | Any, b: np.ndarray | Any, idx: np.ndarray | Any | None = None
) -> np.ndarray:
    """Compute 2D Pareto front (maximize both objectives) using Rust backend."""
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    if a.shape != b.shape or a.ndim != 1:
        raise ValueError((a.shape, b.shape))
    if idx is None:
        if not np.all(np.isfinite(a)) or not np.all(np.isfinite(b)):
            raise ValueError("a and b must be finite")
        return np.asarray(_rust_pareto_front_2d_maximize(a, b), dtype=int)
    idx_arr = np.asarray(idx, dtype=int)
    if idx_arr.ndim != 1:
        raise ValueError(idx_arr.shape)
    n = a.size
    for i in idx_arr:
        if i < 0:
            raise ValueError(f"idx entry {i} is negative")
        if i >= n:
            raise ValueError(f"idx entry {i} is out of bounds for length {n}")
        if not np.isfinite(a[i]) or not np.isfinite(b[i]):
            raise ValueError("a and b must be finite")
    return np.asarray(_rust_pareto_front_2d_maximize(a, b, idx_arr), dtype=int)


def arms_from_pareto_fronts(
    x_cand: np.ndarray | Any,
    mu: np.ndarray | Any,
    se: np.ndarray | Any,
    num_arms: int,
    rng: Generator | Any,
) -> np.ndarray:
    x_array = np.asarray(x_cand, dtype=np.float64)
    mu_array = np.asarray(mu, dtype=np.float64)
    se_array = np.asarray(se, dtype=np.float64)
    if x_array.ndim != 2:
        raise ValueError(x_array.shape)
    if mu_array.shape != se_array.shape or mu_array.ndim != 1:
        raise ValueError((mu_array.shape, se_array.shape))
    if mu_array.size != x_array.shape[0]:
        raise ValueError((mu_array.size, x_array.shape[0]))
    num_arms = int(num_arms)
    if num_arms <= 0:
        raise ValueError(num_arms)
    if not np.all(np.isfinite(mu_array)) or not np.all(np.isfinite(se_array)):
        raise ValueError("mu and se must be finite")
    seed = int(rng.integers(0, 2**63 - 1))
    result = _rust_arms_from_pareto_fronts(x_array, mu_array, se_array, num_arms, seed)
    return np.asarray(result, dtype=x_array.dtype)

use std::path::{Path, PathBuf};
use std::process::Command;

pub fn blas_libs_present(dir: &Path) -> bool {
    ["libblas.so", "libopenblas.so", "libopenblas.so.0"]
        .iter()
        .any(|name| dir.join(name).exists())
}

pub fn install_patchelf_if_needed() {
    let script =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../ennbo/cmake/install_patchelf_root.sh");
    let status = Command::new("bash")
        .arg(script)
        .status()
        .unwrap_or_else(|e| panic!("install_patchelf_root.sh: {e}"));
    assert!(
        status.success(),
        "install_patchelf_root.sh failed: {status}"
    );
}

pub fn emit_linux_rpath_link_args() {
    println!("cargo:rerun-if-env-changed=CONDA_PREFIX");
    if !cfg!(target_os = "linux") {
        return;
    }
    install_patchelf_if_needed();
    if let Ok(prefix) = std::env::var("CONDA_PREFIX") {
        let lib = PathBuf::from(prefix).join("lib");
        if blas_libs_present(&lib) {
            let p = lib.to_string_lossy();
            println!("cargo:rustc-cdylib-link-arg=-Wl,-rpath,{p}");
        }
    }
    for p in ["/usr/lib/x86_64-linux-gnu", "/usr/lib/aarch64-linux-gnu"] {
        if blas_libs_present(Path::new(p)) {
            println!("cargo:rustc-cdylib-link-arg=-Wl,-rpath,{p}");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::Path;

    #[test]
    fn blas_libs_present_empty_dir() {
        let dir = std::env::temp_dir().join(format!("enn_blas_check_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        assert!(!blas_libs_present(Path::new(&dir)));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn emit_linux_rpath_link_args_smoke() {
        emit_linux_rpath_link_args();
    }
}

use std::path::{Path, PathBuf};

pub fn emit_link_search(p: &str) {
    println!("cargo:rustc-link-search=native={p}");
    println!("cargo:rustc-link-arg=-Wl,-rpath,{p}");
}

pub fn has_faiss_c(dir: &Path) -> bool {
    dir.join("libfaiss_c.dylib").exists() || dir.join("libfaiss_c.so").exists()
}

pub fn has_blas_for_link(dir: &Path) -> bool {
    dir.join("libblas.so").exists()
        || dir.join("libopenblas.so").exists()
        || dir.join("libopenblas.so.0").exists()
}

pub fn openblas_for_link(dir: &Path) -> Option<PathBuf> {
    ["libopenblas.so", "libopenblas.so.0"]
        .iter()
        .map(|name| dir.join(name))
        .find(|path| path.exists())
}

pub fn emit_openblas_link(dir: &Path) {
    if let Some(openblas) = openblas_for_link(dir) {
        println!("cargo:rustc-link-arg={}", openblas.display());
        println!("cargo:rustc-link-arg=-Wl,-rpath,{}", dir.display());
    }
}

pub fn emit_blas_lapack_link_search_linux() {
    if let Ok(prefix) = std::env::var("CONDA_PREFIX") {
        let lib = PathBuf::from(prefix).join("lib");
        if has_blas_for_link(&lib) {
            println!(
                "cargo:rustc-link-search=native={}",
                lib.to_str().expect("utf-8 conda lib path")
            );
            emit_openblas_link(&lib);
        }
    }
    for p in ["/usr/lib/x86_64-linux-gnu", "/usr/lib/aarch64-linux-gnu"] {
        if has_blas_for_link(Path::new(p)) {
            println!("cargo:rustc-link-search=native={p}");
            emit_openblas_link(Path::new(p));
        }
    }
}

pub fn emit_faiss_link_search() {
    println!("cargo:rerun-if-env-changed=FAISS_LIB_DIR");
    println!("cargo:rerun-if-env-changed=CONDA_PREFIX");
    if let Ok(dir) = std::env::var("FAISS_LIB_DIR") {
        emit_link_search(&dir);
        return;
    }
    if let Ok(prefix) = std::env::var("CONDA_PREFIX") {
        let lib = PathBuf::from(prefix).join("lib");
        if has_faiss_c(&lib) {
            emit_link_search(lib.to_str().expect("utf-8 conda lib path"));
            return;
        }
    }
    if cfg!(target_os = "macos") {
        for p in ["/opt/homebrew/opt/faiss/lib", "/usr/local/opt/faiss/lib"] {
            if has_faiss_c(Path::new(p)) {
                emit_link_search(p);
                return;
            }
        }
    }
    if cfg!(target_os = "linux") {
        for p in ["/usr/lib/x86_64-linux-gnu", "/usr/lib/aarch64-linux-gnu"] {
            if has_faiss_c(Path::new(p)) {
                emit_link_search(p);
                return;
            }
        }
        emit_blas_lapack_link_search_linux();
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::Path;

    #[test]
    fn has_faiss_c_empty_dir() {
        let dir = std::env::temp_dir().join(format!("enn_faiss_check_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        assert!(!has_faiss_c(Path::new(&dir)));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn has_blas_for_link_empty_dir() {
        let dir = std::env::temp_dir().join(format!("enn_blas_link_{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        assert!(!has_blas_for_link(Path::new(&dir)));
        assert!(openblas_for_link(Path::new(&dir)).is_none());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn emit_faiss_link_search_smoke() {
        emit_faiss_link_search();
    }
}

